#!/usr/bin/env node
/**
 * Inline the built worker and worklet as string exports, so a host that
 * cannot resolve `new URL('./filmstrip-worker.js', import.meta.url)` can
 * still construct them from a Blob URL (design spec decision 10).
 *
 * Run by `npm run build` AFTER tsc. It OVERWRITES the compiled
 * `dist/inline-sources.generated.js` — tsc emits that file from the
 * checked-in `src/inline-sources.generated.ts` stub, which exports empty
 * strings. The emitted `.d.ts` is deliberately left alone: the stub
 * annotates both exports as `string`, which stays true of the real values.
 *
 * Constrains: src/inline-sources.ts (its only consumer).
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const dist = join(dirname(fileURLToPath(import.meta.url)), '..', 'dist');

function readBuilt(name) {
  const path = join(dist, name);
  if (!existsSync(path)) {
    console.error(`gen-inline-sources: ${path} is missing — run tsc first`);
    process.exit(1);
  }
  // Strip the sourceMappingURL comment: inside a Blob URL the relative
  // .map path resolves to nothing and only produces a console 404.
  return readFileSync(path, 'utf8').replace(
    /^\/\/# sourceMappingURL=.*$/gm,
    ''
  );
}

const out =
  '// GENERATED by scripts/gen-inline-sources.mjs during `npm run build`.\n' +
  '// Overwrites the compiled stub from src/inline-sources.generated.ts.\n' +
  `export const FILMSTRIP_WORKER_SOURCE = ${JSON.stringify(readBuilt('filmstrip-worker.js'))};\n` +
  `export const VOICE_CAPTURE_WORKLET_SOURCE = ${JSON.stringify(readBuilt('voice-capture-worklet.js'))};\n`;

const target = join(dist, 'inline-sources.generated.js');
writeFileSync(target, out);
console.log(
  `gen-inline-sources: wrote ${target} (${out.length} bytes)`
);
